import requests

BASE_URL = "https://api.socbench.example"

# Retrieve the top-rated products across all categories.
top_rated_response = requests.get(f"{BASE_URL}/products/top-rated")
top_rated_response.raise_for_status()
top_rated_categories = top_rated_response.json()

# Collect product IDs and names, keeping the highest sustainability rating per product.
products_by_id = {}
for category in top_rated_categories:
    for product in category.get("products", []):
        product_id = product.get("productId")
        if not product_id:
            continue
        existing = products_by_id.get(product_id)
        if existing is None or product.get("sustainabilityRating", 0) > existing.get(
            "sustainabilityRating", 0
        ):
            products_by_id[product_id] = {
                **product,
                "categoryId": category.get("categoryId"),
            }

# Fetch product descriptions and sustainability details, plus pricing for comparison.
results = []
for product_id, product in products_by_id.items():
    search_response = requests.get(
        f"{BASE_URL}/products/search",
        params={"query": product.get("productName", product_id), "page": 1, "size": 100},
    )
    search_response.raise_for_status()
    search_data = search_response.json()

    matching_details = next(
        (
            item
            for item in search_data.get("products", [])
            if item.get("productId") == product_id
        ),
        {},
    )

    rating_response = requests.get(f"{BASE_URL}/products/{product_id}/rating")
    rating_response.raise_for_status()

    prices_response = requests.get(f"{BASE_URL}/products/{product_id}/prices")
    prices_response.raise_for_status()
    prices = prices_response.json()

    # Flag differing prices for the same currency; the API provides no endpoint
    # for submitting price updates or suggested changes.
    prices_by_currency = {}
    for price in prices:
        prices_by_currency.setdefault(price.get("currency"), []).append(price)

    discrepancies = {}
    for currency, entries in prices_by_currency.items():
        values = [entry.get("price") for entry in entries if entry.get("price") is not None]
        if len(set(values)) > 1:
            average_price = sum(values) / len(values)
            discrepancies[currency] = {
                "prices": entries,
                "suggestedPrice": round(average_price, 2),
            }

    results.append(
        {
            "product": product,
            "details": matching_details,
            "sustainability": rating_response.json(),
            "prices": prices,
            "pricingDiscrepancies": discrepancies,
        }
    )

# Retrieve available consumer trends and regional demand forecasts.
trends_response = requests.get(f"{BASE_URL}/consumer-trends/overview")
trends_response.raise_for_status()

forecast_response = requests.get(f"{BASE_URL}/inventory/demand-forecast")
forecast_response.raise_for_status()

report = {
    "topRatedProducts": results,
    "consumerTrends": trends_response.json(),
    "demandForecast": forecast_response.json(),
}

