import os
import requests

BASE_URL = "https://api.socbench.example"
TOKEN = os.getenv("API_TOKEN")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if TOKEN:
    session.headers.update({"Authorization": f"Bearer {TOKEN}"})


def get_json(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", **kwargs)
    response.raise_for_status()
    return response.json()


top_categories = get_json("/product-categories/top")
inventory = get_json("/inventory-levels")
retailers = get_json("/retailers")
locations = get_json("/locations")

def items(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("categories", "retailers", "locations", "inventory", "items", "data", "results"):
            if isinstance(data.get(key), list):
                return data[key]
    return []


category_items = items(top_categories)
retailer_items = items(retailers)
location_items = items(locations)
inventory_items = items(inventory)

def value(obj, *keys):
    if not isinstance(obj, dict):
        return None
    for key in keys:
        if obj.get(key) is not None:
            return obj[key]
    return None


category_ids = {
    str(value(category, "id", "category_id", "categoryId"))
    for category in category_items
    if value(category, "id", "category_id", "categoryId") is not None
}
category_names = {
    str(value(category, "name", "category", "title")).casefold()
    for category in category_items
    if value(category, "name", "category", "title") is not None
}

retailers_by_id = {
    str(value(retailer, "id", "retailer_id", "retailerId")): retailer
    for retailer in retailer_items
    if value(retailer, "id", "retailer_id", "retailerId") is not None
}

matching_retailers = {}
for retailer_id, retailer in retailers_by_id.items():
    try:
        products_data = get_json(f"/retailers/{retailer_id}/products")
    except requests.HTTPError:
        continue

    products = items(products_data)
    matching_products = []
    for product in products:
        product_category_id = value(product, "category_id", "categoryId")
        product_category_name = value(product, "category", "category_name", "categoryName")
        if (
            product_category_id is not None and str(product_category_id) in category_ids
        ) or (
            product_category_name is not None
            and str(product_category_name).casefold() in category_names
        ):
            matching_products.append(product)

    if matching_products:
        matching_retailers[retailer_id] = {
            "retailer": retailer,
            "products": matching_products,
        }

relevant_inventory = []
for record in inventory_items:
    record_category_id = value(record, "category_id", "categoryId")
    record_category_name = value(record, "category", "category_name", "categoryName")
    if (
        record_category_id is not None and str(record_category_id) in category_ids
    ) or (
        record_category_name is not None
        and str(record_category_name).casefold() in category_names
    ):
        relevant_inventory.append(record)

analysis = {
    "top_demand_categories": category_items,
    "inventory_levels": inventory_items,
    "retailers_offering_top_categories": matching_retailers,
    "available_retailers": retailer_items,
    "store_locations": location_items,
    "relevant_category_inventory": relevant_inventory,
}

print(analysis)

